// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Synth} from "../src/Synth.sol";

contract InvMutTest is Test {
    Synth c;
    function setUp() public { c = new Synth(address(this), address(new __InvMutHandleStub())); }

    function testFuzz_property(address spender, uint256 initialAllowance, uint256 addedValue) public {
        // Admissible spender: nonzero, and not this test contract (to avoid self-call noise).
        vm.assume(spender != address(0));
        vm.assume(spender != address(this));

        // Keep inputs in a wide but non-degenerate domain.
        // type(uint256).max is a saturating special case in C's _approve; exclude it so
        // the buggy version's no-op truly differs from the reference.
        initialAllowance = bound(initialAllowance, 0, type(uint256).max - 1);
        addedValue = bound(addedValue, 1, type(uint256).max - initialAllowance);

        c.approve(spender, initialAllowance);
        uint256 beforeAllowance = c.allowance(address(this), spender);

        bool ok = true;
        try c.increaseAllowance(spender, addedValue) returns (bool ret) {
            // The reference always returns true here; record it for the rule.
            ok = ret;
        } catch {
            ok = false;
        }

        uint256 afterAllowance = c.allowance(address(this), spender);

        // General rule: a successful increaseAllowance adds exactly addedValue to the
        // caller's allowance and returns true.
        assertTrue(ok && afterAllowance == beforeAllowance + addedValue);
    }
}

contract __InvMutHandleStub {
    function factory() external view returns (address) { return address(this); }
    function createPair(address, address) external view returns (address) { return address(this); }
    function underlying() external view returns (address) { return address(this); }
    function WETH() external view returns (address) { return address(this); }
    function name() external pure returns (string memory) { return "S"; }
    function symbol() external pure returns (string memory) { return "S"; }
    function decimals() external pure returns (uint8) { return 18; }
    function totalSupply() external pure returns (uint256) { return 0; }
    function balanceOf(address) external pure returns (uint256) { return 0; }
    function allowance(address, address) external pure returns (uint256) { return 0; }
    function approve(address, uint256) external pure returns (bool) { return true; }
    function transfer(address, uint256) external pure returns (bool) { return true; }
    function transferFrom(address, address, uint256) external pure returns (bool) { return true; }
    receive() external payable {}
    fallback() external payable {}
}
